def configure(base, template=None):
    values = {
        "PID": PID,
        "SHORT": SHORT,
        "SHA": SHA,
        "TYPE": TYPE,
        "YEAR": YEAR,
        "PAGE_COUNT": PAGE_COUNT,
        "TEXT_DIR": TEXT_DIR,
        "STAGE": STAGE,
        "CHAPTERS": CHAPTERS,
        "PATTERNS": PATTERNS,
        "MOVES": MOVES,
        "EXAMPLES": EXAMPLES,
    }
    for name, value in values.items():
        setattr(base, name, value)
        if template is not None:
            setattr(template, name, value)


def build_language(base, template, pages):
    configure(base, template)
    language = base.build_language(template, pages)
    for unit in language["units"]:
        unit["function"] = "Preserve a source-anchored coach-evaluation move and transfer it only after replacing roster, aspect, metric, benchmark, weight, era, sport, and decision scope."
        unit["reusable_pattern"] = "decision context or metric -> typed weighting, ranking, comparison, or transfer -> inspectable output -> scoped handoff"
        unit["information_order"] = ["audience, roster, aspect, era, sport, or parameter", "definition, formula, matrix, normalization, comparison, or rerun", "grade, distance, hit score, rank, or list", "condition and receiving use"]
        unit["reusable_elements"] = ["explicit roster and metric scope", "defined indicator direction", "ordered model operation", "result before evidence boundary"]
        unit["prohibited_generalizations"] = ["Do not present one roster, media benchmark, gender sample, sport mapping, or president transfer as universal ranking truth.", "Do not detach a count, average, weight, membership, entropy, distance, hit score, or rank from its definition and source."]
        unit["features"]["quantitative_role"] = "bind a record, average, playoff count, award weight, matrix entry, membership, entropy, offset, time weight, hit score, or rank to its declared role"
        unit["features"]["transition"] = "first, second, afterwards, accordingly, in conclusion, however, and at last connect metrics, models, checks, extensions, and communication"
    for layout in language["chapter_layouts"]:
        layout["counting_method"] = "All 33 local UTF-8 page files were read in bounded page ranges; chapter counts use declared physical-page ranges, and all 33 rendered pages received byte-bounded visual review."
        layout["ambiguities"] = ["Extraction flattens matrices, roots, sums, subscripts, table columns, bold rank changes, and plotted labels; visual checks preserve uncertainty instead of silently repairing the source.", "Media rankings, interpolation, judgmental weights, and transferred metrics are evidence boundaries recorded after positive language and organization learning."]
        if layout["chapter"] == "abstract":
            layout["paragraph_count"] = 6
            layout["paragraph_functions"] = [
                "Define five aspects and secondary metrics with a playoff-data example.",
                "Sequence AHP and FSE, including membership, entropy, and weighted grades.",
                "Define hit-score evaluation, compare the two models, aggregate them, and name the basketball top five.",
                "Introduce six time periods, gender application, and cross-sport football and hockey lists.",
                "Preview three sensitivity studies and the president-ranking exploration.",
                "Close with strengths, weaknesses, nontechnical explanation, and future work.",
            ]
        elif layout["chapter"] == "introduction":
            layout["paragraph_count"] = 9
            layout["paragraph_functions"] = [
                "Identify Sports Illustrated and the century-wide multi-sport coach decision.",
                "State the metric-and-model construction task.",
                "State the performance-evaluation-system task.",
                "State the time, gender, and sport-transfer task.",
                "State the parameter influence and broader-application task.",
                "Locate prior media rankings as context.",
                "Introduce AHP as a structured evaluation precedent.",
                "Introduce fuzzy set theory and FSE as the second precedent.",
                "Map Sections 2 through 9 from definitions to future work.",
            ]
    return language


def equation(index, page, label, latex, symbols, purpose, confidence="high"):
    return {
        "equation_id": f"EQ-B-{YEAR}-{SHORT}-{index:03d}",
        "page": page,
        "label": label,
        "source_expression": latex,
        "normalized_latex": latex,
        "purpose": purpose,
        "variable_symbols": symbols,
        "source_type": "paper",
        "visual_checked": True,
        "transcription_confidence": confidence,
    }


def make_model(base, template, model_id, page, section, family, purpose, inputs, outputs, equations):
    configure(base, template)
    model = base.make_model(template, model_id, page, section, family, purpose, inputs, outputs, equations)
    model["summary"] = purpose
    for variable in model["variables"]:
        variable["definition"] = f"Source-defined coach-evaluation quantity {variable['symbol']}."
        variable["unit"] = "annual count, career count, average rating, weight, matrix entry, membership, entropy, distance, hit score, rank, or dimensionless grade as defined by the source"
    model["objectives"] = [purpose, "Return a typed aspect grade, criterion weight, membership, component score, aggregate rank, sensitivity response, or communication artifact."]
    model["constraints"] = ["Keep roster, sport, era, indicator direction, source, normalization, judgment, benchmark, and rank scope explicit.", "Media-list agreement, subgroup fit, cross-sport reuse, or sensitivity-optimal hit score does not establish causal validity or universal ranking truth."]
    model["conditions"] = {
        "initial": {"status": "present", "details": ["A declared candidate roster, five aspect definitions, eighteen secondary indicators, source records, and weighting or benchmark inputs are supplied or assumed."]},
        "boundary": {"status": "present", "details": ["Missing values, media-list composition, rank ties, era cutoffs, gender roster, sport mapping, membership family, and transferred-domain definitions require explicit handling."]},
        "equilibrium": {"status": "not-applicable", "details": ["The paper executes finite scoring, ranking, comparison, transfer, and parameter-sweep calculations rather than a dynamical equilibrium solve."]},
    }
    model["parameter_estimation"] = {"status": "partial", "method": "Internet records, hand-coded contribution values, one-nine AHP judgments, eigenvectors, entropy shares, media ranking offsets, judgmental period weights, and hit-score sweeps.", "parameters": [v["symbol"] for v in model["variables"]]}
    model["algorithm"] = {"status": "partial", "steps": ["freeze roster, aspect hierarchy, secondary metrics, and source meanings", "calculate aspect values and AHP or FSE component grades", "evaluate component ranks against declared media lists and aggregate them", "rerun the interface for gender, time, sport, function, and weight scenarios", "handoff qualified lists to the nontechnical explanation"], "software": ["The paper supplies tables and formulas but no frozen input dataset, executable source code, environment, or complete run log."], "convergence_criteria": "Finite matrix, entropy, distance, aggregation, and sweep operations terminate directly; no independent validation or uncertainty certificate is supplied."}
    model["assumptions"] = ["The retained five aspects and eighteen secondary metrics represent the intended comparison within the declared roster.", "The collected records, interpolated values, AHP judgments, media rankings, time weights, and transfer mappings are sufficiently comparable for the stated exercise."]
    model["identifiability_feasibility"] = {"status": "partial", "analysis": "The hierarchy, equations, tables, ranks, flow chart, and sensitivity plots are inspectable, but the frozen data, coding decisions, media lists, calculation files, and independent validation are absent."}
    model["computational_cost"] = "Driven by small dense AHP matrices, candidate-by-indicator normalization, entropy calculations, media-list distance comparisons, ranking reruns, and parameter sweeps."
    model["strengths"] = ["The paper exposes a long positive chain from metric definitions through two component models, aggregation, extensions, sensitivity, and audience communication.", "Intermediate hierarchy, tables, distances, hit scores, before-and-after ranks, and sensitivity plots make the intended calculation route inspectable."]
    model["limitations"] = ["The same media hit-score benchmark is used for model evaluation and parameter selection, so the checks are not independent.", "Confirmed formula, table, symbol, generalization, and reproducibility issues remain last-pass warnings only."]
    model["missing_details"] = ["Frozen coach and media datasets, retrieval dates, interpolation code, pairwise-judgment provenance, contribution coding, time-weight derivation, sport mappings, executable calculations, uncertainty analysis, and independent validation data are absent."]
    return model


